window.bookSummaryJSON = "<p><b>An ordinary girl, a dream to become extraordinary, and the powers that will lead her to change the world.</b></p> <p>What would you do if you were invited to study at the Magical Arts Academy?</p> <p>Enroll, of course!</p> <p>Join Isadora and her crew of magical misfits.</p> <p>Embark on a wild adventure today!</p> <p><b><i>Omnibus Three </i></b><b>includes books 9-13 of the Magical Arts Academy:</b></p> <ul> <li><i>Castle's Curse</i></li> <li><i>Spirited Escape</i></li> <li><i>Dragon's Fury</i></li> <li><i>Magic Ignites</i></li> <li><i>Powers Unleashed</i></li> </ul>"; 
